Let's try all possible orderings of the operations to reach $\frac{11}{5}$ starting from $\frac{1}{5}$. The allowed operations are $A = +1$, $M = \times 2$, and $D = +\frac{2}{5}$. We want to avoid the intermediate result $\frac{6}{5}$.

\begin{itemize}
    \item $A \times M \times D$: $\frac{1}{5} + 1 = \frac{6}{5} \xrightarrow{M} \frac{6}{5} \times 2 = \frac{12}{5} \xrightarrow{D} \frac{12}{5} + \frac{2}{5} = \frac{14}{5}$. This gives $\frac{14}{5}$, and since $\frac{6}{5}$ is an intermediate result, this is not allowed.
    \item $A \times D \times M$: $\frac{1}{5} + 1 = \frac{6}{5} \xrightarrow{D} \frac{6}{5} + \frac{2}{5} = \frac{8}{5} \xrightarrow{M} \frac{8}{5} \times 2 = \frac{16}{5}$. This gives $\frac{16}{5}$, and since $\frac{6}{5}$ is an intermediate result, this is not allowed.
    \item $M \times A \times D$: $\frac{1}{5} \times 2 = \frac{2}{5} \xrightarrow{A} \frac{2}{5} + 1 = \frac{7}{5} \xrightarrow{D} \frac{7}{5} + \frac{2}{5} = \frac{9}{5}$. This gives $\frac{9}{5}$.
    \item $M \times D \times A$: $\frac{1}{5} \times 2 = \frac{2}{5} \xrightarrow{D} \frac{2}{5} + \frac{2}{5} = \frac{4}{5} \xrightarrow{A} \frac{4}{5} + 1 = \frac{9}{5}$. This gives $\frac{9}{5}$.
    \item $D \times A \times M$: $\frac{1}{5} + \frac{2}{5} = \frac{3}{5} \xrightarrow{A} \frac{3}{5} + 1 = \frac{8}{5} \xrightarrow{M} \frac{8}{5} \times 2 = \frac{16}{5}$. This gives $\frac{16}{5}$.
    \item $D \times M \times A$: $\frac{1}{5} + \frac{2}{5} = \frac{3}{5} \xrightarrow{M} \frac{3}{5} \times 2 = \frac{6}{5} \xrightarrow{A} \frac{6}{5} + 1 = \frac{11}{5}$. This gives $\frac{11}{5}$, and since $\frac{6}{5}$ is an intermediate result, this is not allowed.
\end{itemize}
